class BankAccount:
    """
    A simple representation of a bank account that supports deposit,
    withdrawal, and balance checking with basic validation.
    """

    def __init__(self, initial_balance=0):
        # Ensure the initial balance is not negative
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative.")
        self._balance = int(initial_balance)

    def deposit(self, amount):
        """
        Deposit a positive amount into the account.
        """
        # Validate amount is an int (or can be cast to int) and positive
        try:
            amount_int = int(amount)
        except (TypeError, ValueError):
            print("Deposit amount must be a valid integer.")
            return
        if amount_int <= 0:
            print("Deposit amount must be positive.")
            return
        # Update balance
        self._balance += amount_int
        print(self._balance)

    def withdraw(self, amount):
        """
        Withdraw a positive amount if sufficient funds are available.
        """
        try:
            amount_int = int(amount)
        except (TypeError, ValueError):
            print("Withdrawal amount must be a valid integer.")
            return
        if amount_int <= 0:
            print("Withdrawal amount must be positive.")
            return
        if amount_int > self._balance:
            print("Insufficient funds for withdrawal.")
            return
        # Perform withdrawal
        self._balance -= amount_int
        print(self._balance)

    def check_balance(self):
        """
        Print the current balance.
        """
        print(self._balance)


def main():
    """
    Reads commands from standard input and executes them on a BankAccount.
    """
    import sys
    account = BankAccount()
    while True:
        try:
            line = input()
        except EOFError:
            # In some environments (e.g., when input is piped and ends), break
            break
        if not line.strip():
            continue  # skip empty lines
        parts = line.strip().split()
        if not parts:
            continue
        cmd = parts[0].upper()

        if cmd == 'EXIT':
            break
        elif cmd == 'DEPOSIT':
            # Only one argument for amount
            if len(parts) != 2:
                print("Invalid DEPOSIT command.")
                continue
            try:
                amount = int(parts[1])
            except ValueError:
                print("Deposit amount must be a valid integer.")
                continue
            account.deposit(amount)
        elif cmd == 'WITHDRAW':
            if len(parts) != 2:
                print("Invalid WITHDRAW command.")
                continue
            try:
                amount = int(parts[1])
            except ValueError:
                print("Withdrawal amount must be a valid integer.")
                continue
            account.withdraw(amount)
        elif cmd == 'BALANCE':
            account.check_balance()
        else:
            # Unknown command
            print("Unknown command.")

if __name__ == "__main__":
    main()

